/**
 * Zoom limits for the receipt viewer.
 *
 * 100% means fit-to-viewport, not 1:1 — so a flat maximum percentage means
 * different things on different screens. The ceiling is therefore derived from
 * the individual image: zoom stops where one image pixel fills one CSS pixel.
 * See the "Zoom never invents pixels" invariant in `docs/domain-model.md`.
 */

export interface FitDimensions {
	width: number;
	height: number;
}

/** The floor, and the meaning of "fit to viewport". */
export const MIN_ZOOM = 100;

/** Zoom in/out snap to multiples of this. */
export const ZOOM_STEP = 50;

/**
 * The size an image occupies at 100% zoom: scaled down to fit the viewport box,
 * never scaled up. An image smaller than the box is already at native size, so
 * 100% is also its ceiling.
 */
export function calculateFitDimensions(
	naturalWidth: number,
	naturalHeight: number,
	viewportWidth: number,
	viewportHeight: number
): FitDimensions {
	const scale = Math.min(viewportWidth / naturalWidth, viewportHeight / naturalHeight, 1);
	return { width: naturalWidth * scale, height: naturalHeight * scale };
}

/**
 * The zoom percentage at which the image is displayed at its true resolution —
 * the point past which further magnification would only interpolate.
 *
 * Returns MIN_ZOOM when the image is already at (or below) native size on
 * screen, which is what disables the zoom controls: there are no further real
 * pixels to show, and a greyed-out control says so honestly.
 */
export function calculateMaxZoom(naturalWidth: number, baseWidth: number): number {
	if (baseWidth <= 0) return MIN_ZOOM;
	return Math.max(MIN_ZOOM, (naturalWidth / baseWidth) * MIN_ZOOM);
}

/**
 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
 *
 * Turns the **Source File** a person picked into the **Receipt Image** we store:
 * at most 2400px on the longest axis, JPEG at 85%, whatever arrived. The size
 * limits in `ReceiptService` describe the result of this function, not its
 * input — see `docs/adr/0006-the-stored-image-is-the-contract.md`.
 */

export interface ResizeDimensions {
	width: number;
	height: number;
}

/** Longest-axis budget for a stored Receipt Image. Chosen for human zoom, not OCR. */
export const MAX_IMAGE_DIMENSION = 2400;

/** JPEG quality for a stored Receipt Image. */
export const IMAGE_QUALITY = 0.85;

/** Every stored Receipt Image is a JPEG; only PDFs pass through untouched. */
const OUTPUT_TYPE = 'image/jpeg';

/** The image types the receipts upload control offers. */
const RESIZABLE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];

/**
 * Whether a Source File of this type should be decoded and re-encoded.
 *
 * HEIC is included deliberately: Safari — the only place HEIC originates — can
 * decode it into a Canvas, and skipping it sent full-resolution phone photos
 * straight to storage. Anything else (PDFs, and image types we never offer) is
 * stored exactly as received.
 */
export function isResizableImage(mimeType: string): boolean {
	return RESIZABLE_TYPES.includes(mimeType);
}

/**
 * Rename a Source File to match the JPEG we actually store, so the storage
 * object's extension is not a lie. This never affects `original_filename`
 * (#{#ofn2a}), which keeps the name the person recognizes.
 */
export function toJpegFilename(filename: string): string {
	return filename.replace(/(\.[^./\\]*)?$/, '.jpg');
}

/**
 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
 *
 * Acceptance Criteria:
 * - Maximum dimension on longest axis must be MAX_IMAGE_DIMENSION
 * - Aspect ratio must be preserved during resize
 * - Images already within the budget keep original dimensions
 *
 * @param originalWidth - Original image width in pixels
 * @param originalHeight - Original image height in pixels
 * @param maxSize - Maximum dimension on longest axis
 * @returns New dimensions with preserved aspect ratio
 */
export function calculateResizeDimensions(
	originalWidth: number,
	originalHeight: number,
	maxSize: number = MAX_IMAGE_DIMENSION
): ResizeDimensions {
	const longestAxis = Math.max(originalWidth, originalHeight);

	// If image is already smaller than max, keep original dimensions
	if (longestAxis <= maxSize) {
		return { width: originalWidth, height: originalHeight };
	}

	// Calculate scale factor
	const scale = maxSize / longestAxis;

	// Calculate new dimensions (preserve aspect ratio)
	return {
		width: Math.round(originalWidth * scale),
		height: Math.round(originalHeight * scale)
	};
}

/** Promise-shaped `canvas.toBlob`, which is callback-only. */
function encodeCanvas(canvas: HTMLCanvasElement, quality: number): Promise<Blob> {
	return new Promise((resolve, reject) => {
		canvas.toBlob(
			(blob) => (blob ? resolve(blob) : reject(new Error('Failed to encode image'))),
			OUTPUT_TYPE,
			quality
		);
	});
}

/**
 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
 *
 * Acceptance Criteria:
 * - JPEG, PNG and HEIC are all resized, and all come out as JPEG. PNG could not
 *   honour a quality setting while it stayed PNG — `toBlob` ignores the argument
 *   for lossless formats — so a PNG "resize" used to be able to grow the file.
 * - Resizing occurs client-side (browser) before upload
 * - Images already within the budget are still re-encoded, and so still shrink
 * - EXIF orientation is honoured (#{#rsz2b})
 * - The file is decoded ONCE. `createImageBitmap` is itself the decode; the
 *   `<img>` element this used to load first was a second full decode of the same
 *   bytes, doubling peak memory on exactly the large photos we now accept.
 *
 * Throws if the image cannot be decoded or encoded — the caller decides whether
 * that is fatal.
 *
 * @param file - Source File
 * @param maxSize - Maximum dimension on longest axis
 * @param quality - Compression quality 0-1
 * @returns The Receipt Image to store
 */
export async function resizeImage(
	file: File,
	maxSize: number = MAX_IMAGE_DIMENSION,
	quality: number = IMAGE_QUALITY
): Promise<File> {
	if (!isResizableImage(file.type)) {
		return file;
	}

	// #{#rsz2b} - createImageBitmap applies EXIF orientation as it decodes
	const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' });

	try {
		const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);

		const canvas = document.createElement('canvas');
		canvas.width = width;
		canvas.height = height;

		const ctx = canvas.getContext('2d');
		if (!ctx) throw new Error('Canvas context not available');
		ctx.drawImage(bitmap, 0, 0, width, height);

		const blob = await encodeCanvas(canvas, quality);

		return new File([blob], toJpegFilename(file.name), {
			type: OUTPUT_TYPE,
			lastModified: file.lastModified
		});
	} finally {
		bitmap.close();
	}
}

