/**
 * Zoom-limit arithmetic for the receipt viewer.
 *
 * The invariant under test is "zoom never invents pixels" (see the domain model):
 * 100% means fit-to-viewport, so the ceiling is a property of the individual
 * image rather than a fixed percentage. These are the pure calculations; the
 * component test drives the resulting button states.
 */
import { describe, it, expect } from 'vitest';
import { MIN_ZOOM, calculateFitDimensions, calculateMaxZoom } from './imageZoom';

describe('calculateFitDimensions', () => {
	it('shrinks an image larger than the viewport, preserving aspect ratio', () => {
		// 4000x3000 into a 1800x1000 box — height is the binding constraint
		const fit = calculateFitDimensions(4000, 3000, 1800, 1000);

		expect(fit.height).toBeCloseTo(1000, 5);
		expect(fit.width / fit.height).toBeCloseTo(4000 / 3000, 5);
	});

	it('uses width as the constraint for a wide image', () => {
		const fit = calculateFitDimensions(4000, 1000, 1800, 1000);

		expect(fit.width).toBeCloseTo(1800, 5);
		expect(fit.height).toBeCloseTo(450, 5);
	});

	it('never enlarges an image that already fits', () => {
		const fit = calculateFitDimensions(400, 300, 1800, 1000);

		expect(fit).toEqual({ width: 400, height: 300 });
	});

	it('leaves an image exactly the size of the viewport alone', () => {
		const fit = calculateFitDimensions(1800, 1000, 1800, 1000);

		expect(fit).toEqual({ width: 1800, height: 1000 });
	});
});

describe('calculateMaxZoom', () => {
	it('is the zoom at which one image pixel fills one CSS pixel', () => {
		// Displayed at 900px wide from a 2400px source — 1:1 arrives at 266.67%
		expect(calculateMaxZoom(2400, 900)).toBeCloseTo(266.667, 2);
	});

	it('collapses to the minimum when the image is already shown at native size', () => {
		expect(calculateMaxZoom(400, 400)).toBe(MIN_ZOOM);
	});

	it('never drops below the minimum, even if the base somehow exceeds natural', () => {
		expect(calculateMaxZoom(400, 800)).toBe(MIN_ZOOM);
	});

	it('gives a full-resolution receipt more room than a resized one', () => {
		// Same display size; the pre-resize original simply has more pixels to give.
		expect(calculateMaxZoom(4000, 900)).toBeGreaterThan(calculateMaxZoom(2400, 900));
	});

	it('reports the minimum while the natural size is still unknown', () => {
		expect(calculateMaxZoom(0, 0)).toBe(MIN_ZOOM);
	});
});
